89	    87	            .Find(p => p.PeriodStart == start && p.PeriodEnd == end)
90	    88	            .FirstOrDefaultAsync();
91	    89	
92	    90	        var run = new PayrollRun
93	    91	        {
94	    92	            Id = existing?.Id,
95	    93	            PeriodStart = start,
96	    94	            PeriodEnd = end,
97	    95	            RunDate = DateTime.UtcNow,
