104	   102	        // SCHEDULED sessions to COMPLETED (had attendees) or NO_SHOW (empty).
105	   103	        // We pay commissions only for COMPLETED sessions — classes that actually
106	   104	        // happened with at least one arrived attendee.
107	   105	        var sessions = await _sessions
108	   106	            .Find(s => s.StartTime >= start && s.StartTime <= end
109	   107	                    && s.Status == "COMPLETED"
110	   108	                    && s.Origin != "BLOCK")
111	   109	            .ToListAsync();
