117	   115	            if (string.IsNullOrEmpty(instructorId)) continue;
118	   116	
119	   117	            var staff = await _staff.Find(s => s.Id == instructorId).FirstOrDefaultAsync();
120	   118	            if (staff is null) continue;
121	   119	
122	   120	            // Not yet employed this period — no pay.
123	   121	            if (staff.EmploymentStartDate.HasValue && end < staff.EmploymentStartDate.Value) continue;
