125	   123	            // Resolve the in-force rate revision for the period END. Using End
126	   124	            // (not Start) matches what a payroll clerk expects — "pay people
127	   125	            // under whatever rate was in effect when the month closed". The
128	   126	            // revision service lazily bootstraps a baseline if there is no
129	   127	            // revision yet (legacy staff rows), so the result is never null
130	   128	            // for an existing staff member.
131	   129	            var revision = await _revisions.ResolveAsOfAsync(staff.Id!, end);
132	   130	
133	   131	            // Monthly commission override takes precedence over the revision.
134	   132	            revision = await ApplyCommissionOverrideAsync(staff.Id!, end, revision);
135	   133	
136	   134	            var result = await AggregateInstructorAsync(staff, revision, group.ToList());
