138	   136	        }
139	   137	
140	   138	        // ── Revenue-split commission pass ───────────────────────────────
141	   139	        // Some staff (e.g. an owner-operator) earn a % of the studio's TOTAL
142	   140	        // monthly revenue rather than per-class commission. The rate can be
143	   141	        // tiered on that revenue (e.g. 4% under 100M, 5% at/over). These people
144	   142	        // may not teach at all, so they won't appear in the session loop above —
145	   143	        // process them here from the month's paid revenue.
146	   144	        var revenueSplitStaff = await _staff
147	   145	            .Find(s => s.CommissionModel == "REVENUE_SPLIT")
148	   146	            .ToListAsync();
149	   147	        if (revenueSplitStaff.Count > 0)
150	   148	        {
