152	   150	            // is a pass-through surcharge, so exclude OnlineFeeAmount from the base.
153	   151	            var monthlyRevenue = (await _invoices
154	   152	                .Find(i => i.IssueDate >= start && i.IssueDate <= end && i.Status == "PAID")
155	   153	                .ToListAsync()).Sum(i => i.TotalNet - i.OnlineFeeAmount);
156	   154	
157	   155	            foreach (var staff in revenueSplitStaff)
158	   156	            {
159	   157	                // Not yet employed this period — no commission.
160	   158	                if (staff.EmploymentStartDate.HasValue && end < staff.EmploymentStartDate.Value) continue;
161	   159	
162	   160	                decimal pct;
163	   161	                if (staff.RevenueCommissionTiers is { Count: > 0 } rtiers)
164	   162	                {
165	   163	                    var rung = rtiers
166	   164	                        .Where(t => monthlyRevenue >= t.MinRevenue
167	   165	                                 && (t.MaxRevenue == null || monthlyRevenue < t.MaxRevenue.Value))
168	   166	                        .OrderByDescending(t => t.MinRevenue)
169	   167	                        .FirstOrDefault()
170	   168	                        ?? rtiers.OrderByDescending(t => t.MinRevenue).First();
