457	   455	                }
458	   456	            }
459	   457	            else
460	   458	            {
461	   459	                result.TotalPrivateClasses++;
462	   460	                totalClassesWithAttendees++;
463	   461	
464	   462	                if (result.CommissionModelSnapshot == "FIXED_HEADCOUNT")
465	   463	                {
466	   464	                    var seatHeadcount = arrivedAttendances
467	   465	                        .Where(a => a.CountsTowardsCommission)
468	   466	                        .Sum(a => Math.Max(1, a.Quantity));
469	   467	
470	   468	                    result.PrivateClassEarnings += ResolveHeadcountPayoutFromSnapshot(result, seatHeadcount, isPrivate: true);
471	   469	                }
472	   470	                else
473	   471	                {
474	   472	                    foreach (var att in arrivedAttendances)
475	   473	                    {
476	   474	                        if (!att.CountsTowardsCommission) continue;
477	   475	
478	   476	                        var revenueBase = await ResolveAttendeeRevenueAsync(att, session);
479	   477	
480	   478	                        // Apply referral discount.
481	   479	                        var discountPct = att.ReferralDiscountPct.HasValue
482	   480	                            ? Math.Clamp(att.ReferralDiscountPct.Value, 0m, 1m)
483	   481	                            : 0m;
484	   482	                        var seatRev = revenueBase * (1m - discountPct);
485	   483	                        if (att.PromoDiscountAmount is > 0m)
486	   484	                            seatRev = Math.Max(0m, seatRev - att.PromoDiscountAmount.Value);
487	   485	                        privateRawRevenue += seatRev;
488	   486	                    }
489	   487	                }
490	   488	            }
491	   489	        }
492	   490	
493	   491	        // ── Apply tiered commission rates ──────────────────────────────
494	   492	        // For PERCENTAGE_TIERED, the tier is resolved using the TOTAL class
495	   493	        // count (group + private) that had at least one arrived attendee.
496	   494	        // The same rate applies to both group and private raw revenue.
497	   495	        if (result.CommissionModelSnapshot == "PERCENTAGE_TIERED")
498	   496	        {
499	   497	            var totalCountForTier = totalClassesWithAttendees;
500	   498	            var tieredRate = ResolvePrivateCommissionRateFromSnapshot(result, totalCountForTier);
501	   499	            result.PrivateClassEarnings = privateRawRevenue * tieredRate;
502	   500	            result.GroupClassEarnings += groupRawRevenue * tieredRate;
503	   501	        }
504	   502	        else if (result.CommissionModelSnapshot != "FIXED_HEADCOUNT")
505	   503	        {
506	   504	            // Non-tiered flat model: apply the flat private commission rate to the
507	   505	            // raw revenue accumulated in the loop.
508	   506	            //
509	   507	            // FIXED_HEADCOUNT MUST be excluded here. Its private earnings are already
510	   508	            // final — computed per-session from the headcount tiers inside the loop
511	   509	            // (see ResolveHeadcountPayoutFromSnapshot above). This branch would
512	   510	            // otherwise overwrite that with `privateRawRevenue * privateRate`, and
513	   511	            // privateRawRevenue is only ever accumulated on the percentage path, so
514	   512	            // for a headcount instructor it is 0 — zeroing out every private-class
515	   513	            // commission (the Linna bug).
516	   514	            var privateRate = ResolvePrivateCommissionRateFromSnapshot(result, result.TotalPrivateClasses);
517	   515	            result.PrivateClassEarnings = privateRawRevenue * privateRate;
518	   516	        }
519	   517	
520	   518	        // Fold in the verbatim spreadsheet-imported commissions AFTER the tier
521	   519	        // logic (which overwrites PrivateClassEarnings for PERCENTAGE_TIERED).
522	   520	        result.GroupClassEarnings += importedGroupComm + overrideGroupComm;
523	   521	        result.PrivateClassEarnings += importedPrivateComm + overridePrivateComm;
524	   522	
525	   523	        result.TotalPay = result.BaseSalaryAmount + result.GroupClassEarnings + result.PrivateClassEarnings;
526	   524	        return result;
527	   525	    }
