665	   663	    /// <summary>
666	   664	    /// SPM-113 — money: decides whether an arrived attendee has actually PAID,
667	   665	    /// and therefore whether they count toward the instructor's commission
668	   666	    /// (earnings, head-count payout, and tier thresholds alike). Genuinely
669	   667	    /// unpaid monetary arrivals are excluded everywhere.
670	   668	    ///
671	   669	    /// <para>Paid rules (owner decision):</para>
672	   670	    /// <list type="bullet">
673	   671	    ///   <item><c>PACKAGE_CREDIT</c> bookings are always paid (the credit was
674	   672	    ///   purchased up front).</item>
675	   673	    ///   <item>Free classes (<see cref="Attendance.IsFreeClass"/>) count as
676	   674	    ///   satisfied — they are deliberately 0₫ revenue, NOT unpaid debt.</item>
677	   675	    ///   <item>Monetary bookings are paid when a linked <see cref="Invoice"/>
678	   676	    ///   has <c>Status == "PAID"</c>, OR <see cref="Attendance.AmountPaid"/>
679	   677	    ///   is &gt; 0, OR <see cref="Attendance.AmountDueAtStudio"/> is null/0
680	   678	    ///   (nothing left to collect at the studio).</item>
681	   679	    /// </list>
682	   680	    ///
683	   681	    /// <para>The invoice lookup mirrors the one in
684	   682	    /// <see cref="ResolveAttendeeRevenueAsync"/> so the two surfaces stay
685	   683	    /// consistent. This is a pure read — re-runs remain idempotent.</para>
686	   684	    /// </summary>
687	   685	    private async Task<bool> IsAttendancePaidAsync(Attendance att)
688	   686	    {
689	   687	        // Package-credit redemptions were paid for when the package was bought.
690	   688	        if (att.PaymentMethod == "PACKAGE_CREDIT") return true;
691	   689	
692	   690	        // Free classes are satisfied (0₫ by design, not an unpaid balance).
693	   691	        if (att.IsFreeClass) return true;
694	   692	
695	   693	        // Direct evidence of payment on the attendance row.
696	   694	        if ((att.AmountPaid ?? 0m) > 0m) return true;
697	   695	
698	   696	        // Nothing left to collect at the studio ⇒ treated as paid. (null is
699	   697	        // treated as "no outstanding balance" — matches legacy rows that
700	   698	        // pre-date the field and the fully-prepaid online flow.)
701	   699	        if ((att.AmountDueAtStudio ?? 0m) <= 0m) return true;
702	   700	
703	   701	        // Otherwise, a linked PAID invoice settles it. Mirrors the invoice
704	   702	        // lookup in ResolveAttendeeRevenueAsync.
705	   703	        var linkedInvoice = await _invoices.Find(
706	   704	            Builders<Invoice>.Filter.ElemMatch(
707	   705	                i => i.Lines,
708	   706	                Builders<InvoiceLine>.Filter.Eq(l => l.AttendanceId, att.Id)
709	   707	            )
710	   708	        ).FirstOrDefaultAsync();
711	   709	
712	   710	        return linkedInvoice is not null && linkedInvoice.Status == "PAID";
713	   711	    }
