715	   713	    /// <summary>
716	   714	    /// Resolves the revenue attributed to a single attendee for commission
717	   715	    /// calculation. Uses the linked invoice's paid balance as the source of
718	   716	    /// truth; falls back to the session's snapshotted DropInPrice when no
719	   717	    /// invoice exists (e.g. package credit or pre-paid bookings).
720	   718	    /// </summary>
721	   719	    private async Task<decimal> ResolveAttendeeRevenueAsync(Attendance att, CalendarSession session)
722	   720	    {
723	   721	        var qty = Math.Max(1, att.Quantity);
724	   722	
725	   723	        // ── Package-credit bookings ──────────────────────────────────────
726	   724	        // When a client redeems a pre-paid package, the invoice shows 0₫ (no new
727	   725	        // money changed hands), but the instructor's commission must be based on
728	   726	        // the class's value. Business rule (studio policy): the commission base is
729	   727	        // the per-class rate WITHIN the package — i.e. what the package sold for
730	   728	        // divided by its credits — NOT the full drop-in rate. That per-class value
731	   729	        // is stored on the ClientPackage as FractionalValuePerClass.
732	   730	        if (att.PaymentMethod == "PACKAGE_CREDIT")
733	   731	        {
734	   732	            if (!string.IsNullOrEmpty(att.PackageInstanceId))
735	   733	            {
736	   734	                var pkg = await _clientPackages
737	   735	                    .Find(p => p.Id == att.PackageInstanceId)
738	   736	                    .FirstOrDefaultAsync();
739	   737	                if (pkg is not null && pkg.FractionalValuePerClass > 0m)
740	   738	                    return pkg.FractionalValuePerClass * qty;
741	   739	            }
742	   740	            // Fallback only when the package's per-class value is unknown
743	   741	            // (e.g. missing package link) — the session's drop-in price.
744	   742	            return (session.DropInPrice ?? 0m) * qty;
745	   743	        }
746	   744	
747	   745	        // ── Monetary-payment bookings ────────────────────────────────────
748	   746	        // 1. Try to find a linked invoice for this attendance and use its
749	   747	        //    actual paid amount (TotalNet) as the revenue base.
750	   748	        var linkedInvoice = await _invoices.Find(
751	   749	            Builders<Invoice>.Filter.ElemMatch(
752	   750	                i => i.Lines,
753	   751	                Builders<InvoiceLine>.Filter.Eq(l => l.AttendanceId, att.Id)
754	   752	            )
755	   753	        ).FirstOrDefaultAsync();
756	   754	
757	   755	        // The "VAT (online only)" surcharge is a pass-through fee, NOT studio
758	   756	        // revenue, so it must never be part of the commission base. It is stored
759	   757	        // separately as Invoice.OnlineFeeAmount (never inside a line), so the
760	   758	        // per-line total below is already fee-free; only the whole-invoice and
761	   759	        // AmountPaid fallbacks need the fee stripped out. Apportion the fee to
762	   760	        // this attendee by their share of the invoice's line subtotal.
763	   761	        decimal onlineFeeShare = 0m;
764	   762	        if (linkedInvoice is not null && linkedInvoice.OnlineFeeAmount > 0m)
765	   763	        {
766	   764	            var lineSubtotal = linkedInvoice.Lines.Sum(l => l.UnitPrice * l.Quantity - l.LineDiscount);
767	   765	            var myLine = linkedInvoice.Lines.FirstOrDefault(l => l.AttendanceId == att.Id);
768	   766	            var myLineTotal = myLine is not null ? (myLine.UnitPrice * myLine.Quantity - myLine.LineDiscount) : 0m;
769	   767	            onlineFeeShare = (lineSubtotal > 0m && myLineTotal > 0m)
770	   768	                ? linkedInvoice.OnlineFeeAmount * (myLineTotal / lineSubtotal)
771	   769	                : linkedInvoice.OnlineFeeAmount; // single-booking invoice: exclude the whole fee
772	   770	        }
773	   771	
774	   772	        if (linkedInvoice is not null && linkedInvoice.Status == "PAID")
775	   773	        {
776	   774	            // Prefer the specific line total (already excludes the online fee).
777	   775	            // Note: invoice line already includes quantity in its total.
778	   776	            var line = linkedInvoice.Lines
779	   777	                .FirstOrDefault(l => l.AttendanceId == att.Id);
780	   778	            if (line is not null)
781	   779	            {
782	   780	                var lineTotal = line.UnitPrice * line.Quantity - line.LineDiscount;
783	   781	                if (lineTotal > 0m) return lineTotal;
784	   782	            }
785	   783	            // Whole-invoice fallback: strip the online fee out of the net.
786	   784	            var netExFee = linkedInvoice.TotalNet - linkedInvoice.OnlineFeeAmount;
787	   785	            if (netExFee > 0m) return netExFee;
788	   786	        }
789	   787	
790	   788	        // 2. If the attendance has a recorded paid amount, use that — less this
791	   789	        //    attendee's share of any online fee that was bundled into the payment.
792	   790	        if ((att.AmountPaid ?? 0m) > 0m)
793	   791	        {
794	   792	            return Math.Max(0m, (att.AmountPaid ?? 0m) - onlineFeeShare);
795	   793	        }
796	   794	
797	   795	        // 3. No monetary payment recorded (e.g. booked "pay at studio" but the
798	   796	        //    client is a package member). Business rule: if the client holds an
799	   797	        //    active package for THIS class format, the class draws from that
800	   798	        //    package — commission on the package's per-class rate, NOT the full
801	   799	        //    drop-in. Only genuine full-price drop-in payments (captured in steps
802	   800	        //    1–2 above) commission on the drop-in rate.
803	   801	        if (!string.IsNullOrEmpty(session.Format))
804	   802	        {
805	   803	            var memberPkg = await _clientPackages
806	   804	                .Find(p => p.ClientId == att.ClientId
807	   805	                           && p.Format == session.Format
808	   806	                           && p.FractionalValuePerClass > 0m
809	   807	                           && (p.Status == "ACTIVE" || p.Status == "LOW_BALANCE"))
810	   808	                .FirstOrDefaultAsync();
811	   809	            if (memberPkg is not null)
812	   810	                return memberPkg.FractionalValuePerClass * qty;
813	   811	        }
814	   812	
815	   813	        // 4. Fallback: session's snapshotted drop-in price × quantity.
816	   814	        return (session.DropInPrice ?? 0m) * qty;
817	   815	    }
