820	   818	    /// Looks up the commission rate that applies to the given private-class count
821	   819	    /// for this staff member, reading from the live <see cref="Staff"/> document.
822	   820	    ///
823	   821	    /// <para>
824	   822	    /// Preserved for backward compatibility with the test suite + the instructor
825	   823	    /// self-service portal's tier-progress meter (which reads the LIVE rate
826	   824	    /// sheet to compute "X more classes until your next tier" — that's a
827	   825	    /// forecast, not a historical fact, so the live sheet is correct here).
828	   826	    /// </para>
829	   827	    ///
830	   828	    /// <para>
831	   829	    /// The payroll calculation itself goes through
832	   830	    /// <see cref="ResolvePrivateCommissionRateFromSnapshot"/> instead, so it
833	   831	    /// is unaffected by future edits to <c>Staff</c>.
834	   832	    /// </para>
835	   833	    /// </summary>
836	   834	    public static decimal ResolvePrivateCommissionRate(Staff staff, int privateClassCount)
837	   835	    {
838	   836	        if (!staff.HasTieredPrivateCommission || staff.Tiers.Count == 0)
839	   837	        {
840	   838	            return NormalizeCommissionPct(staff.FlatPrivateCommissionPct);
841	   839	        }
842	   840	        var matching = staff.Tiers
843	   841	            .Where(t => privateClassCount >= t.MinClasses
844	   842	                     && (!t.MaxClasses.HasValue || privateClassCount <= t.MaxClasses.Value))
845	   843	            .OrderByDescending(t => t.CommissionPercentage)
846	   844	            .FirstOrDefault();
847	   845	        return NormalizeCommissionPct(matching?.CommissionPercentage ?? staff.FlatPrivateCommissionPct);
848	   846	    }
